import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import '../styles/ManageGigs.css';

const ManageGigPostings = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();

  const fetchGigs = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/gigs/list?username=${searchTerm}`);
      setGigs(response.data);
    } catch (error) {
      console.error("Error fetching gigs:", error);
    }
  };

  const handleDelete = async (gigId) => {
    if (window.confirm("Are you sure you want to delete this gig?")) {
      try {
        await axios.delete(`http://localhost:5000/api/gigs/${gigId}`);
        alert("Gig deleted successfully");
        fetchGigs(); // Refresh list
      } catch (err) {
        console.error("Failed to delete gig:", err);
      }
    }
  };

  useEffect(() => {
    if (searchTerm) fetchGigs();
  }, [searchTerm]);

  return (
    <div className="manage-gig-postings">
      <h2>Manage Gig Postings</h2>
      <input 
        type="text" 
        className="search-bar" 
        placeholder="Search by username..." 
        value={searchTerm} 
        onChange={(e) => setSearchTerm(e.target.value)} 
      />
      <div className="gig-list">
        {gigs.length > 0 ? gigs.map((gig) => (
          <div className="gig-item" key={gig._id}>
            <p><strong>{gig.title}</strong> — Expires: {gig.expiryDate?.split("T")[0]}</p>
            <button className="view-button" onClick={() => navigate(`/gig/${gig._id}`)}>View Gig</button>
            <button className="delete-button" onClick={() => handleDelete(gig._id)}>Delete Gig</button>
          </div>
        )) : <p>No gigs found.</p>}
      </div>
    </div>
  );
};

export default ManageGigPostings;
